import React, { useState, useEffect, useRef } from 'react';
import { 
  ScatterChart, 
  Scatter, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  ComposedChart, 
  Legend, 
  Label 
} from 'recharts';

function BeatSnapDivisorChart() {
  const [bpmInput, setBpmInput] = useState("200");
  const [bpm, setBpm] = useState(200);
  const [beatLength, setBeatLength] = useState(300); // ms
  const [chartData, setChartData] = useState([]);
  const [enhancedPositions, setEnhancedPositions] = useState([]);
  const [divisorMarkers, setDivisorMarkers] = useState({});
  const [activeMarkerIndex, setActiveMarkerIndex] = useState(null);
  const [mouseX, setMouseX] = useState(null);
  const timelineRef = useRef(null);
  
  const divisors = [5, 7, 9, 12, 16];
  
  // Helper function to format position text
  const formatPositionText = (value) => {
    return value !== null ? value.toFixed(2) : '---';
  };
  
  // Calculate snap points when component loads
  useEffect(() => {
    calculateSnapPointsForBPM(bpm);
  }, []);
  
  // Find positions that should show MS labels
  const getPositionsToShowLabels = (positions, beatLength) => {
    if (!positions || positions.length === 0) return new Set();
    
    const targets = [
      0,
      beatLength/6,
      beatLength/3,
      beatLength/2,
      2*beatLength/3,
      5*beatLength/6,
      beatLength
    ];
    
    const positionsToShow = new Set();
    
    // Always include first and last positions
    if (positions.length > 0) {
      positionsToShow.add(positions[0].position);
      positionsToShow.add(positions[positions.length - 1].position);
    }
    
    // For each middle target, find closest position
    for (let i = 1; i < targets.length - 1; i++) {
      const target = targets[i];
      let closestPos = null;
      let minDistance = Infinity;
      
      positions.forEach(pos => {
        const distance = Math.abs(pos.position - target);
        if (distance < minDistance) {
          minDistance = distance;
          closestPos = pos.position;
        }
      });
      
      if (closestPos !== null) {
        positionsToShow.add(closestPos);
      }
    }
    
    return positionsToShow;
  };
  
  // Function to handle BPM input change
  const handleBpmInputChange = (e) => {
    const inputValue = e.target.value;
    
    // Allow empty string and valid numbers only
    if (inputValue === "") {
      setBpmInput("");
      return;
    }
    
    // Make sure it's a number and <= 999
    const numValue = parseInt(inputValue, 10);
    if (!isNaN(numValue)) {
      if (numValue > 999) {
        setBpmInput("999");
        setBpm(999);
      } else if (numValue > 0) {
        setBpmInput(inputValue);
        setBpm(numValue);
      } else {
        setBpmInput(inputValue);
      }
    }
  };

  // Effect to calculate beat length when BPM changes
  useEffect(() => {
    if (bpm > 0) {
      calculateSnapPointsForBPM(bpm);
    }
  }, [bpm]);
  
  // Function to calculate snap point positions given a BPM
  const calculateSnapPointsForBPM = (bpm) => {
    const newBeatLength = 60000 / bpm; // ms per beat at given BPM
    setBeatLength(newBeatLength);
    
    // Generate all snap points with their divisors
    const allPoints = [];
    const newDivisorMarkers = {};
    
    divisors.forEach(divisor => {
      newDivisorMarkers[divisor] = [];
      const interval = newBeatLength / divisor;
      
      for (let i = 0; i <= divisor; i++) {
        const position = i * interval;
        
        // Add to combined points
        allPoints.push({
          position,
          divisor
        });
        
        // Add to divisor-specific markers
        newDivisorMarkers[divisor].push({
          position,
          divisor
        });
      }
    });
    
    // Sort all points
    allPoints.sort((a, b) => a.position - b.position);
    
    // Group points by position (with small tolerance for floating point)
    const groupedPoints = [];
    if (allPoints.length > 0) {
      let currentGroup = {
        position: allPoints[0].position,
        divisors: [allPoints[0].divisor]
      };
      
      for (let i = 1; i < allPoints.length; i++) {
        const point = allPoints[i];
        // If this point is very close to the previous one, consider it the same position
        if (Math.abs(point.position - currentGroup.position) < 0.001) {
          if (!currentGroup.divisors.includes(point.divisor)) {
            currentGroup.divisors.push(point.divisor);
          }
        } else {
          // This is a new position, add the previous group to our results
          groupedPoints.push({...currentGroup});
          // Start a new group
          currentGroup = {
            position: point.position,
            divisors: [point.divisor]
          };
        }
      }
      // Add the last group
      groupedPoints.push(currentGroup);
    }
    
    // Format grouped points for the combined timeline
    const newEnhancedPositions = groupedPoints.map((group, index) => {
      const prevPosition = index > 0 ? groupedPoints[index - 1].position : null;
      const nextPosition = index < groupedPoints.length - 1 ? groupedPoints[index + 1].position : null;
      
      return {
        position: group.position,
        divisors: group.divisors,
        divisorLabels: group.divisors.map(d => `1/${d}`).join(', '),
        prevPosition,
        nextPosition,
        distFromPrev: prevPosition !== null ? group.position - prevPosition : null,
        distToNext: nextPosition !== null ? nextPosition - group.position : null
      };
    });
    
    // Add prev/next info to divisor-specific markers
    const enhancedDivisorMarkers = {};
    
    divisors.forEach(divisor => {
      const markers = newDivisorMarkers[divisor];
      
      enhancedDivisorMarkers[divisor] = markers.map((marker, idx) => {
        const prevPos = idx > 0 ? markers[idx - 1].position : null;
        const nextPos = idx < markers.length - 1 ? markers[idx + 1].position : null;
        
        return {
          ...marker,
          prevPosition: prevPos,
          nextPosition: nextPos,
          distFromPrev: prevPos !== null ? marker.position - prevPos : null,
          distToNext: nextPos !== null ? nextPos - marker.position : null
        };
      });
    });
    
    setEnhancedPositions(newEnhancedPositions);
    setDivisorMarkers(enhancedDivisorMarkers);
    
    // Calculate intervals for the scatter chart
    const intervals = [];
    for (let i = 1; i < newEnhancedPositions.length; i++) {
      const interval = newEnhancedPositions[i].position - newEnhancedPositions[i-1].position;
      const midpoint = (newEnhancedPositions[i].position + newEnhancedPositions[i-1].position) / 2;
      intervals.push({
        midpoint,
        interval
      });
    }
    
    setChartData(intervals);
  };
  
  // Function to handle mouse movement over the timeline
  const handleMouseMove = (e) => {
    if (!timelineRef.current || enhancedPositions.length === 0) return;
    
    const rect = timelineRef.current.getBoundingClientRect();
    
    // Just get the X position relative to the timeline container
    const x = e.clientX - rect.left;
    setMouseX(x);
    
    // Convert to beat position
    const mousePositionInBeat = (x / rect.width) * beatLength;
    
    // Find closest marker
    let closest = 0;
    let minDist = Math.abs(enhancedPositions[0].position - mousePositionInBeat);
    
    for (let i = 1; i < enhancedPositions.length; i++) {
      const dist = Math.abs(enhancedPositions[i].position - mousePositionInBeat);
      if (dist < minDist) {
        minDist = dist;
        closest = i;
      }
    }
    
    setActiveMarkerIndex(closest);
  };
  
  // Reset when mouse leaves
  const handleMouseLeave = () => {
    setMouseX(null);
    setActiveMarkerIndex(null);
  };
  
  // Custom tooltip for the chart
  const CustomTooltip = ({ active, payload }) => {
    if (active && payload && payload.length) {
      return (
        <div className="p-2 border rounded shadow-md bg-gray-800 border-gray-600 text-gray-200">
          <p className="font-semibold">midpoint: {payload[0].payload.midpoint.toFixed(2)} ms</p>
          <p>interval: {payload[0].payload.interval.toFixed(2)} ms</p>
        </div>
      );
    }
    return null;
  };

  // Function to get a color for each divisor
  const getDivisorColor = (divisor) => {
    const colors = {
      5: '#F1C40F',  // Yellow
      7: '#E67E22',  // Orange
      9: '#E91E63',  // Pink
      12: '#8E44AD', // Purple
      16: '#555555'  // Dark Grey
    };
    return colors[divisor] || '#999999';
  };
  
  return (
    <div className="flex flex-col items-center w-full bg-gray-900 text-gray-100 p-6 rounded-lg max-w-6xl mx-auto">
      <h2 className="text-xl font-bold mb-4">beat snap divisors analysis (in common time)</h2>
      
      {/* BPM Input Control */}
      <div className="flex items-center justify-center w-full mb-6">
        <label htmlFor="bpm-input" className="mr-3">bpm:</label>
        <input
          id="bpm-input"
          type="text"
          value={bpmInput}
          onChange={handleBpmInputChange}
          onKeyPress={(e) => {
            // Allow only digits
            if (!/[0-9]/.test(e.key)) {
              e.preventDefault();
            }
          }}
          maxLength={3}
          className="bg-gray-800 text-gray-100 border border-gray-700 rounded px-2 py-1 w-12 text-center"
        />
        <span className="ml-4">beat length: {bpm > 0 ? beatLength.toFixed(2) : "---"} ms</span>
      </div>
      
      <p className="text-lg font-bold mb-4">intervals between adjacent snap points at {bpm} bpm</p>
      
      <div className="w-full h-80 mb-4">
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 50 }}
            className="text-gray-200">
            <CartesianGrid strokeDasharray="3 3" stroke="#444" />
            <XAxis 
              dataKey="midpoint" 
              type="number" 
              domain={[0, beatLength]}
              ticks={[0, beatLength/6, beatLength/3, beatLength/2, 2*beatLength/3, 5*beatLength/6, beatLength]}
              tickFormatter={(value) => value.toFixed(1)}
              stroke="#AAA"
            >
              <Label value="position in beat (ms)" offset={-5} position="insideBottom" fill="#AAA" />
            </XAxis>
            <YAxis 
              stroke="#AAA"
              tickFormatter={(value) => value.toFixed(1)}
            >
              <Label value="interval (ms)" angle={-90} position="insideLeft" style={{ textAnchor: 'middle' }} fill="#AAA" />
            </YAxis>
            <Tooltip content={<CustomTooltip />} />
            <Legend 
              verticalAlign="top" 
              height={36} 
              align="center"
              wrapperStyle={{ width: '100%', justifyContent: 'center' }}
            />
            <Scatter 
              name="intervals" 
              dataKey="interval" 
              fill="#8884d8" 
              legendType="circle"
            />
          </ComposedChart>
        </ResponsiveContainer>
      </div>
      
      {/* Mathematical formulas and explanation with improved readability */}
      <div className="w-full p-4 bg-gray-800 rounded-lg mb-8 text-left">
        <h4 className="text-gray-200 font-semibold mb-3">about this visualisation</h4>
        
        <div className="mb-4">
          <p className="text-sm font-medium text-gray-300 mb-2">the problem:</p>
          <div className="pl-3 border-l-2 border-gray-700 text-xs text-gray-300 space-y-2">
            <p>the current stable editor's available beat snap divisors prove fundamentally inadequate for precise timing adjustments within variable timing contexts.</p>
            
            <p>when dealing with songs featuring variable bpm (particularly where different instrument tracks exhibit micro-timing variations), mappers may encounter situations where the instrument they're mapping requires slightly different offsets from the established uninherited timing points in other difficulties.</p>
            
            <p>the current divisor options (even including expanded divisors like 1/7, 1/9, 1/12, and 1/16) only provide a predetermined grid of snap positions within each beat, with each divisor creating fixed gaps between available snap points, as visualised in the combined timeline below.</p>
            
            <p>this limitation becomes particularly problematic in some variable bpm sections, where the variance between available snap positions is not only <span className="text-gray-400">inconsistent</span>, but can range from single to double-digit milliseconds in common song bpms, as demonstrated in the intervals graph above.</p>
            
          </div>
        </div>
        
        <div className="mb-4">
          <p className="text-sm font-medium text-gray-300 mb-2">what we're visualising:</p>
          <div className="pl-3 border-l-2 border-gray-700 text-xs text-gray-300">
            <p>this tool examines how non-power-of-2 beat snap divisors (1/5, 1/7, 1/9, 1/12, 1/16) interact:</p>
            <ul className="list-disc pl-5 mt-1 space-y-1">
              <li>the <span className="text-gray-400">top graph</span> shows the irregular intervals between adjacent snap points</li>
              <li>the <span className="text-gray-400">middle rows</span> display each divisor's evenly-spaced points</li>
              <li>the <span className="text-gray-400">bottom timeline</span> shows all unique points combined</li>
            </ul>
          </div>
        </div>
        
        <div className="mb-6">
          <p className="text-sm font-medium text-gray-300 mb-2">key insight:</p>
          <div className="pl-3 border-l-2 border-gray-700 text-xs text-gray-300">
            <p>the combined snap points create an inconsistent grid where intervals vary significantly throughout the beat. these gaps are often too large to achieve the precise offsets needed for accurate timing in variable contexts.</p>
            <p className="mt-2">what's particularly noteworthy is that online offset adjustments apply for offset errors as small as 5ms—considerably lower than what the current extended beat snap divisor system allows for in many cases (see average interval between points below).</p>
          </div>
        </div>
        
        <h5 className="text-gray-200 font-medium mb-3">exact calculation method:</h5>
        
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs text-gray-300 bg-gray-900 p-3 rounded">
          <div className="p-2 bg-gray-850 rounded">
            <p className="font-medium mb-1">step 1: calculate beat length</p>
            <p className="ml-2 font-mono">B = 60,000 / BPM ms</p>
            <p className="ml-2 text-gray-400 mt-1 text-xs">current beat length: {beatLength.toFixed(2)} ms at {bpm} bpm</p>
          </div>
          
          <div className="p-2 bg-gray-850 rounded">
            <p className="font-medium mb-1">step 2: generate points for each divisor</p>
            <p className="ml-2 font-mono">P<sub>i,n</sub> = n × (B ÷ i) where n ∈ [0...i]</p>
            <p className="ml-2 text-gray-400 mt-1 text-xs">example: 1/5 points at 0, 60, 120, 180, 240, 300 ms</p>
          </div>
          
          <div className="p-2 bg-gray-850 rounded">
            <p className="font-medium mb-1">step 3: combine and sort all unique points</p>
            <p className="ml-2 font-mono">sort all P<sub>i,n</sub> by position, merging any within 0.001ms</p>
            <p className="ml-2 text-gray-400 mt-1 text-xs">result: array of unique positions with their contributing divisors</p>
          </div>
          
          <div className="p-2 bg-gray-850 rounded">
            <p className="font-medium mb-1">step 4: calculate intervals and midpoints</p>
            <p className="ml-2 font-mono">interval I<sub>j</sub> = P<sub>j+1</sub> - P<sub>j</sub></p>
            <p className="ml-2 font-mono">midpoint M<sub>j</sub> = (P<sub>j</sub> + P<sub>j+1</sub>) ÷ 2</p>
            <p className="ml-2 text-gray-400 mt-1 text-xs">these (M<sub>j</sub>, I<sub>j</sub>) pairs form the scatter plot</p>
          </div>
        </div>
      </div>
      
      <h3 className="text-lg font-bold mt-4 mb-6">snap points visualisation at {bpm} bpm</h3>
      
      <div className="w-full mb-12">
        {/* Individual divisor rows */}
        {divisors.map((divisor) => (
          <div key={divisor} className="w-full h-10 relative mb-4">
            <div className="absolute left-0 top-4 w-8 text-right pr-2 font-semibold" style={{ color: getDivisorColor(divisor) }}>
              1/{divisor}
            </div>
            
            {/* Interval value on the right side */}
            <div className="absolute right-0 top-4 w-20 text-left pl-2 text-gray-400 text-xs">
              {(beatLength / divisor).toFixed(2)}ms
            </div>
            
            {/* Container with specific width to match markers */}
            <div 
              className="relative mx-auto" 
              style={{ width: 'calc(100% - 120px)', marginLeft: '40px' }}
            >
              <div className="w-full h-1 bg-gray-700 absolute top-4"></div>
              
              {divisorMarkers[divisor] && divisorMarkers[divisor].map((marker, idx) => {
                // Calculate percentage position, ensuring first is at start and last is at end
                const isFirst = marker.position === 0;
                const isLast = marker.position === beatLength;
                let leftPosition;
                
                if (isFirst) {
                  leftPosition = 0;
                } else if (isLast) {
                  leftPosition = 100;
                } else {
                  // Stretch other markers between 0-100%
                  leftPosition = (marker.position / beatLength) * 100;
                }
                
                return (
                  <div 
                    key={idx}
                    className="absolute w-1 h-8 -mt-3 rounded-sm"
                    style={{ 
                      left: `${leftPosition}%`,
                      backgroundColor: getDivisorColor(divisor)
                    }}
                  >
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>
      
      <h3 className="text-lg font-bold mt-4 mb-2">combined timeline (all divisors) at {bpm} bpm</h3>
      
      {/* Average interval as a simple label */}
      <div className="flex items-center justify-center w-full mb-4">
        <span className="text-gray-300 text-sm">average interval between points:</span>
        <span className="ml-2 font-mono text-gray-200 text-sm">
          {enhancedPositions.length > 1 
            ? (() => {
                // Calculate sum of all intervals
                let sum = 0;
                let count = 0;
                
                for (let i = 1; i < enhancedPositions.length; i++) {
                  const interval = enhancedPositions[i].position - enhancedPositions[i-1].position;
                  sum += interval;
                  count++;
                }
                
                // Return average with fixed precision
                return (sum / count).toFixed(2) + " ms";
              })()
            : "---"
          }
        </span>
      </div>
      
      {/* Combined timeline with all points */}
      <div className="w-full relative mt-6 mb-16" style={{ height: '80px' }}>
        {/* Header for combined visualization */}
        <div className="absolute left-0 top-4 w-8 text-right pr-2 font-semibold text-gray-200">
          all
        </div>
        
        {/* Main timeline container */}
        <div 
          ref={timelineRef}
          className="ml-10 relative" 
          style={{ width: 'calc(100% - 50px)', height: '100%' }}
        >
          {/* Background line */}
          <div className="w-full h-1 bg-gray-700 absolute top-4"></div>
          
          {/* Dedicated interaction area for hover - extending 20px above and below */}
          <div 
            className="absolute left-0 w-full"
            style={{ 
              top: '-16px',  // -20px plus 4px for the line position
              height: '40px', // 40px total vertical area
              cursor: 'default',
              zIndex: 5 // Ensure this is above the markers
            }}
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
          />
          
          {/* Marker points */}
          {enhancedPositions.map((position, index) => (
            <div 
              key={index}
              className="absolute"
              style={{ 
                left: `${(position.position / beatLength) * 100}%`,
                top: '0',
                marginLeft: activeMarkerIndex === index ? '-1px' : '0'  // Center the marker when active (2px width)
              }}
            >
              <div
                className={activeMarkerIndex === index ? 'w-2 h-10 -mt-4' : 'w-1 h-8 -mt-3'}
                style={{ 
                  backgroundColor: 
                    position.divisors.length > 1 
                      ? '#FFFFFF'  // White for overlaps
                      : getDivisorColor(position.divisors[0]),
                  borderRadius: '1px'
                }}
              />
              
              {/* Static cursor line */}
              {activeMarkerIndex === index && mouseX !== null && (
                <div
                  className="absolute h-12 -mt-5 border-l border-gray-400 pointer-events-none z-10"
                  style={{
                    left: '50%',
                    top: '0',
                    transform: 'translateX(-50%)'
                  }}
                />
              )}
            </div>
          ))}
          
          {/* Static tooltip that never moves */}
          {activeMarkerIndex !== null && mouseX !== null && (
            <div 
              className="absolute z-50 p-2 border rounded shadow-md bg-gray-800 border-gray-600 text-gray-200 text-sm whitespace-nowrap pointer-events-none"
              style={{
                left: `${(enhancedPositions[activeMarkerIndex].position / beatLength) * 100}%`,
                top: '50px',
                transform: 'translateX(-50%)'
              }}
            >
              <p className="font-semibold">position: {formatPositionText(enhancedPositions[activeMarkerIndex].position)} ms</p>
              {enhancedPositions[activeMarkerIndex].divisors.length > 1 && (
                <p>divisors: {enhancedPositions[activeMarkerIndex].divisorLabels}</p>
              )}
              {enhancedPositions[activeMarkerIndex].distFromPrev !== null && (
                <p>previous interval: {formatPositionText(enhancedPositions[activeMarkerIndex].distFromPrev)} ms</p>
              )}
              {enhancedPositions[activeMarkerIndex].distToNext !== null && (
                <p>next interval: {formatPositionText(enhancedPositions[activeMarkerIndex].distToNext)} ms</p>
              )}
            </div>
          )}
        </div>
      </div>
      
      <div className="text-sm text-gray-400 mt-16">
        <p>analysis of non-power-of-2 beat snap divisors: 1/5, 1/7, 1/9, 1/12, and 1/16</p>
        <p className="mt-2">white markers on combined row indicate where multiple divisors overlap</p>
        <p className="mt-2">move cursor over combined timeline to see details about each point</p>
      </div>
      
      {/* Footer */}
      <div className="text-sm text-gray-400 mt-8 pt-8 border-t border-gray-700 w-full text-center">
        <p>osu beat snap divisor analysis • sponny • 2025</p>
      </div>
    </div>
  );
}

export default BeatSnapDivisorChart;